{
  "is_correct": false,
  "has_flawed_reasoning": true,
  "error_type": "product_rule_missing_term",
  "error_summary": "xf(x)를 미분할 때 f(x) 항을 누락했다.",
  "first_wrong_step": "g'(x)=10x+xf'(x)라고 쓴 단계",
  "why_plausible": "학생이 x를 변수 함수가 아니라 단순한 계수처럼 취급했을 가능성이 크다. xf(x)를 'f(x)에 x를 곱한 것'으로만 보고, x 자체도 미분되어야 한다는 점을 놓친 것이다.",
  "missing_concepts": [
    {
      "concept_id": "c1-도함수",
      "concept_name": "derivative function(도함수)",
      "reason": "두 함수의 곱을 미분할 때 u'v+uv'를 적용해야 하는데, uv' 항만 남기고 u'v 항을 누락했다."
    },
    {
      "concept_id": "c1-미분계수",
      "concept_name": "derivative at a point(미분계수)",
      "reason": "f(3)과 f'(3)이 서로 다른 정보라는 구분이 필요하다. 이 문제에서는 두 값이 모두 g'(3)에 들어간다."
    }
  ],
  "related_pattern": "곱의 미분법에서 항 누락 여부를 확인하는 기본 패턴",
  "fix_strategy": "곱이 보이면 먼저 u(x)v(x)로 나누고, u'(x)v(x)+u(x)v'(x)를 기계적으로 적는다. 이 문제에서는 u=x, v=f(x)이므로 (xf(x))'=1·f(x)+x·f'(x)=f(x)+xf'(x)이다.",
  "student_feedback": "방향은 맞았지만 xf(x)를 미분할 때 f(x) 항이 빠졌습니다. x도 하나의 함수이므로 (xf(x))'=f(x)+xf'(x)로 처리해야 합니다.",
  "next_review": [
    {
      "concept_id": "c1-도함수",
      "reason": "곱의 미분법을 다시 확인해야 한다."
    },
    {
      "concept_id": "c1-미분계수",
      "reason": "f(3)과 f'(3)의 역할을 구분해야 한다."
    }
  ],
  "uncertainty": null
}

{
  "is_correct": false,
  "has_flawed_reasoning": true,
  "error_type": "product_rule_missing_term",
  "error_summary": "g'(x)를 구할 때 곱의 미분법에서 두 번째 항을 누락했고, 그 오류가 접선과 넓이 계산까지 전파되었다.",
  "first_wrong_step": "g'(x)=(3x^2-2)f(x)라고 쓴 단계",
  "why_plausible": "앞의 접선 l은 정확히 구했기 때문에 학생은 접선 문제의 큰 흐름은 알고 있다. 그러나 g(x)가 두 함수의 곱이라는 점을 충분히 의식하지 못해, (x^3-2x)만 미분하고 f(x)를 고정된 계수처럼 처리했다.",
  "missing_concepts": [
    {
      "concept_id": "c1-도함수",
      "concept_name": "derivative function(도함수)",
      "reason": "g(x)=(x^3-2x)f(x)를 미분할 때 곱의 미분법을 완전하게 적용하지 못했다."
    },
    {
      "concept_id": "h2-직선방정식",
      "concept_name": "equation of a line(직선의 방정식)",
      "reason": "잘못된 기울기에서 접선식을 세웠기 때문에 후속 넓이 계산 전체가 달라졌다. 다만 핵심 원인은 직선방정식 자체보다 곱의 미분법 오류다."
    }
  ],
  "related_pattern": "기본 미분 오류가 접선 방정식과 도형 넓이 계산으로 전파되는 복합 패턴",
  "fix_strategy": "복합 문제에서는 먼저 미분 단계만 따로 검산한다. 특히 g(x)=A(x)f(x) 꼴이면 g'(x)=A'(x)f(x)+A(x)f'(x)를 적고, 그 다음 접선식을 세워야 한다.",
  "student_feedback": "접선 l을 구한 과정은 맞습니다. 하지만 g'(x)를 구할 때 곱의 미분법 한 항이 빠졌습니다. 이 한 단계의 오류 때문에 접선 m의 기울기, 교점, 넓이가 모두 달라졌습니다.",
  "next_review": [
    {
      "concept_id": "c1-도함수",
      "reason": "곱의 미분법을 복합 함수식에 적용하는 연습이 필요하다."
    },
    {
      "concept_id": "h2-직선방정식",
      "reason": "기울기와 한 점으로 접선식을 세우는 절차를 유지해야 한다."
    }
  ],
  "uncertainty": null
}

{
  "is_correct": false,
  "has_flawed_reasoning": true,
  "error_type": "distance_displacement_confusion",
  "error_summary": "움직인 거리를 구해야 하는데 변위 적분 ∫v(t)dt를 계산했다.",
  "first_wrong_step": "움직인 거리는 ∫_0^2 v(t)dt라고 둔 단계",
  "why_plausible": "속도를 적분하면 위치 변화량이 나온다는 사실은 알고 있었지만, 속도가 음수인 구간에서는 실제 이동거리가 음수로 상쇄되면 안 된다는 점을 놓쳤다.",
  "missing_concepts": [
    {
      "concept_id": "c1-정적분활용",
      "concept_name": "application of definite integral(정적분의 활용)",
      "reason": "움직인 거리는 ∫v(t)dt가 아니라 ∫|v(t)|dt로 계산해야 한다."
    },
    {
      "concept_id": "h1-인수분해",
      "concept_name": "factorization(인수분해)",
      "reason": "v(t)=(t-1)(t-4)로 인수분해하여 부호가 바뀌는 지점을 찾아야 한다."
    }
  ],
  "related_pattern": "속도 함수의 부호를 나누어 움직인 거리를 절댓값 적분으로 계산하는 패턴",
  "fix_strategy": "문제에서 '움직인 거리'라는 표현이 나오면 먼저 v(t)=0인 시각을 찾고, 각 구간의 속도 부호를 확인한 뒤 ∫|v(t)|dt로 계산한다. ∫v(t)dt는 변위이다.",
  "student_feedback": "속도를 적분해야 한다는 방향은 맞습니다. 다만 움직인 거리는 변위와 달라서, 속도가 음수인 구간을 그대로 더하면 안 됩니다. v(t)의 부호가 바뀌는 t=1을 기준으로 절댓값 적분을 해야 합니다.",
  "next_review": [
    {
      "concept_id": "c1-정적분활용",
      "reason": "속도-거리 관계에서 ∫v(t)dt와 ∫|v(t)|dt의 차이를 복습해야 한다."
    },
    {
      "concept_id": "h1-인수분해",
      "reason": "속도 함수의 부호 변화를 찾기 위해 인수분해가 필요하다."
    }
  ],
  "uncertainty": null
}

